1. import upath from 'upath';
2. import { GlobalConfig } from '../../config/global';
3. import { logger } from '../../logger';
4. import { findUpLocal } from '../fs';
5. import { newlineRegex } from '../regex';
6. import { rawExec } from './common';
7. import type { RawExecOptions } from './types';
8. 
9. export function isHermit(): boolean {
10.   return GlobalConfig.get('binarySource') === 'hermit';
11. }
12. 
13. export async function findHermitCwd(cwd: string): Promise<string> {
14.   const relativeCwd = upath.relative(GlobalConfig.get('localDir', ''), cwd);
15.   const hermitFile = await findUpLocal('bin/hermit', relativeCwd);
16. 
17.   if (hermitFile === null) {
18.     throw new Error(`hermit not found for ${cwd}`);
19.   }
20. 
21.   return upath.join(GlobalConfig.get('localDir'), upath.dirname(hermitFile));
22. }
23. 
24. export async function getHermitEnvs(
25.   rawOptions: RawExecOptions,
26. ): Promise<Record<string, string>> {
27.   const cwd = rawOptions.cwd ?? /* istanbul ignore next */ '';
28.   const hermitCwd = await findHermitCwd(cwd);
29.   logger.debug({ cwd, hermitCwd }, 'fetching hermit environment variables');
30.   // with -r will output the raw unquoted environment variables to consume
31.   const hermitEnvResp = await rawExec('./hermit env -r', {
32.     ...rawOptions,
33.     cwd: hermitCwd,
34.   });
35. 
36.   const out: Record<string, string> = {};
37. 
38.   const lines = hermitEnvResp.stdout
39.     .split(newlineRegex)
40.     .map((line) => line.trim())
41.     .filter((line) => line.includes('='));
42.   for (const line of lines) {
43.     const equalIndex = line.indexOf('=');
44.     const name = line.substring(0, equalIndex);
45.     out[name] = line.substring(equalIndex + 1);
46.   }
47. 
48.   return out;
49. }
