             ?.childWithAttribute('key', child.attr.key)
             ?.childrenNamed('package')
             .map((packagePattern) => packagePattern.attr.pattern);

           logger.debug(
             {
               name: child.attr.key,
               registryUrl,
               sourceMappedPackagePatterns,
             },
